/* evaluasi generik: fungsi check -> {ok, xp, hp, okT, noT} */
function evalScene(id,lv,title,form,story,instr,body,check,okT,noT,xp,hp){
 return {sub:6,crumb:"Tantangan Akhir",render(st){
  if(QC[id]){const q=QC[id];st.innerHTML=qShell(q,lv,title,story,instr,xp,hp);hudQ();}
  else
  st.innerHTML=status(0,lv)+`<h1>${title}</h1><span class="tag">${form}</span><div class="sc"><div class="big">🧭</div><p>${story}</p></div><p><b>${instr}</b></p><div id="ev"></div><div id="fbk"></div><p><button class="bt y" id="chk" disabled>Periksa Jawaban</button></p>`;
  const ev=$('#ev'),chk=$('#chk');let ready=false;
  const api={ready(v){chk.disabled=!v||state.done[id]},};
  body(ev,api);
  chk.onclick=()=>{const r=check();state.done[id]=1;if(r){state.xp+=xp;$('#fbk').innerHTML=FB.ok(okT+` <b>+${xp} XP │ -0 HP</b>`)}else{state.hp=Math.max(0,state.hp-hp);$('#fbk').innerHTML=FB.no(noT+` <b>+0 XP │ -${hp} HP</b>`)}
   if(QC[id]){hudQ();$('#fbk').innerHTML='';const m=$('#l1m');$(r?'#l1r':'#l1g').style.display='none';const open=()=>{m.hidden=false},close=()=>{m.hidden=true};$('#l1x').onclick=close;m.onclick=e=>{if(e.target===m)close()};open();chk.textContent='Lihat Umpan Balik';chk.onclick=open;chk.disabled=false}else{$('.st').outerHTML=status(0,lv);chk.disabled=true};ev.style.pointerEvents='none';$('#next').disabled=false};
 },lock:id}}
/* helper: pilih kartu ke slot (klik atau drag) */
function slots(labels,cards,answer,multi){return (ev,api)=>{const pick={};let sel=null;
 const S=E('div'),C=E('div');ev.append(S,C);
 const draw=()=>{S.innerHTML='';labels.forEach((l,i)=>{const s=E('div','slot'+(pick[i]!=null?' f':''),`<label>${l}</label>${pick[i]!=null?cards[pick[i]]:'<span style="color:var(--mut)">Lepaskan kartu di sini</span>'}`);
  s.ondragover=e=>e.preventDefault();s.ondrop=e=>{put(i,+e.dataTransfer.getData('t'))};s.onclick=()=>{if(sel!=null)put(i,sel);else if(pick[i]!=null){delete pick[i];draw()}};S.append(s)});
  C.innerHTML='';cards.forEach((t,k)=>{if(Object.values(pick).includes(k))return;const o=E('div','opt'+(sel===k?' sel':''),t);o.draggable=true;o.ondragstart=e=>e.dataTransfer.setData('t',k);o.onclick=()=>{sel=sel===k?null:k;draw()};C.append(o)});
  api.ready(Object.keys(pick).length===labels.length)};
 function put(i,k){for(const x in pick)if(pick[x]===k)delete pick[x];pick[i]=k;sel=null;draw()}
 draw();ev._get=()=>pick};}
