/* ===== GERBANG KELULUSAN: Materi berikutnya hanya terbuka jika XP >= GATE.xp dan HP >= GATE.hp ===== */
(()=>{
const RES=['1.5.7','2.10.6','3.4.6','4.8.7'],INTRO=['1.5.1','2.10.1','3.4.1','4.8.1'];
state.px={};let cur=null;
const passed=()=>state.xp>=GATE.xp&&state.hp>=GATE.hp;
/* XP satu Pos dihitung sekali: mengulang Pos menggantikan XP percobaan sebelumnya, bukan menambah */
SC.forEach(z=>{
 if(z.lock&&z.m>=2){const r=z.render;z.render=s=>{state.xp-=state.px[z.id]||0;state.px[z.id]=0;cur={id:z.id,base:state.xp};r(s)}}
 if(INTRO.includes(z.id)){const r=z.render;z.render=s=>{state.px={};cur=null;r(s)}}
});
const fin=()=>{if(cur){state.px[cur.id]=state.xp-cur.base;cur=null}};window.__gamiFin=fin;
const study=m=>go(first(m));
function post(){
 const sc=SC[i];if(!sc||!RES.includes(sc.id))return;
 const m=sc.m||1,unlocked=prog[m]==2;
 if(!unlocked)$('#next').disabled=true;
 if(passed())return;
 $('#prev').disabled=true;
 const re=$('#re');
 if(re){
  if(re.classList.contains('ov')){
   const b=re.cloneNode(false);b.id='re';b.removeAttribute('aria-label');
   b.style.cssText=re.style.cssText.replace(/pointer-events:\s*none;?/,'')+';background:linear-gradient(#ff6f8a,#f0486a);color:#fff;font:800 1.15cqw/1 Poppins,system-ui,sans-serif;white-space:nowrap;box-shadow:0 .3cqw 0 #c93556;pointer-events:auto';
   b.textContent='📚 Pelajari Materi dari Awal';b.onclick=()=>study(m);re.replaceWith(b);
  }else{const p=re.closest('p');p?p.remove():re.remove()}
 }
 const nx=$('#nxt');
 if(nx&&!unlocked){nx.style.cssText+=';background:#d9d5ee;color:#5c5690;font:800 1.3cqw/1 Poppins,system-ui,sans-serif;pointer-events:none;cursor:not-allowed';nx.textContent='🔒 Terkunci';nx.disabled=true}
 const why=[];if(state.xp<GATE.xp)why.push('XP Anda '+state.xp.toLocaleString('id-ID')+', kurang '+(GATE.xp-state.xp)+' dari batas minimal '+GATE.xp);if(state.hp<GATE.hp)why.push('HP Anda habis');
 const nxt=m<4?'Materi '+(m+1)+' masih terkunci.':'Materi 4 belum dinyatakan selesai.';
 $('#stage').insertAdjacentHTML('beforeend',`<div class="fx" id="gate" style="margin-top:14px;background:#fff4d8;color:#1d1654;border:2px solid #ffd23f;border-radius:22px;padding:18px 22px;text-align:center"><div style="font-size:34px">🔒</div><h2 style="margin:4px 0">${nxt}</h2><p style="margin:6px 0 12px">Syarat lulus: XP minimal <b>${GATE.xp}</b> dan HP tidak habis. ${why.join('; ')}.<br>Pelajari kembali materi dari halaman pertama, lalu kerjakan tantangannya lagi.</p><button class="bt y" id="study" style="font-size:16px">📚 Pelajari Materi dari Awal</button></div>`);
 $('#study').onclick=()=>study(m);
}
const _g=go;
go=function(n){
 if(typeof n=='number'){
  const t=SC[Math.max(0,Math.min(SC.length-1,n))],m=t.m||1;
  if(!can(m)){msg('Materi '+m+' masih terkunci. Lulus Materi '+(m-1)+' dulu (XP minimal '+GATE.xp+', HP tidak habis).');return}
 }
 fin();_g(n);post();
};
})();

